537		if err != nil || replay || tk.ID != "T0005" {
538			t.Fatalf("新报修应开出 T0005: %v replay=%v err=%v", tk, replay, err)
539		}
540		// 旧请求重放不影响新单。
541		old, replay, err = s.report("EQ-1", "卡纸", "req-1")
542		if err != nil || !replay || old.Status != ticketCancelled {
543			t.Fatalf("已有新单时重放仍返回已取消的 T0001: %v replay=%v err=%v", old, replay, err)
