545		if got := s.openTicketOf("EQ-1"); got == nil || got.ID != "T0005" {
546			t.Fatalf("新工单 T0005 应仍为未关闭，得到 %v", got)
547		}
548		// 取消新工单并保存重开：取消状态、理由、履历与去重结果保持。
549		if _, _, err := s.cancelTicket("T0005", "用户自行解决"); err != nil {
550			t.Fatal(err)
551		}
552		if err := s.save(); err != nil {
553			t.Fatal(err)
554		}
555		s2, err := openStore(dir)
556		if err != nil {
557			t.Fatal(err)
558		}
559		got := s2.findTicket("T0005")
560		if got.Status != ticketCancelled || got.CancelReason != "用户自行解决" || got.CancelledAt == "" {
561			t.Fatalf("重开后 T0005 取消状态未保持: %+v", got)
562		}
563		if got := s2.findTicket("T0001"); got.Status != ticketCancelled ||
564			got.CancelReason != "误报，设备实际正常" {
565			t.Fatalf("重开后 T0001 取消状态未保持: %+v", got)
566		}
567		events := s2.eventsOf("EQ-1")
568		if len(events) != 4 || events[0].Kind != eventReport || events[1].Kind != eventCancel ||
569			events[2].Kind != eventReport || events[3].Kind != eventCancel {
570			t.Fatalf("重开后履历不对: %+v", events)
571		}
572		if events[1].Content != "误报，设备实际正常" || events[3].Content != "用户自行解决" {
573			t.Fatalf("取消履历内容应为取消理由: %+v", events)
574		}
575		// 同标识搭配不同资产或描述仍被拒绝，取消不释放旧请求标识。
576		if _, _, err := s2.report("EQ-1", "别的故障", "req-1"); err == nil {
577			t.Fatal("同标识不同描述应被拒绝")
578		}
579	}
580	
581	// 工单编号耗尽时仍可取消已有工单。
582	func TestTicketNumberExhaustionAllowsCancel(t *testing.T) {
583		dir := t.TempDir()
584		writeLedger(t, dir, func(m map[string]any) { m["next_ticket_seq"] = math.MaxInt })
585	
586		var out, errBuf bytes.Buffer
587		code := run([]string{"cancel", "--data-dir", dir, "--ticket-id", "T0001", "--reason", "误报"},
588			&out, &errBuf)
589		if code != 0 {
590			t.Fatalf("编号耗尽时取消已有工单应可用: %s", errBuf.String())
591		}
592		if !strings.Contains(out.String(), "T0001") || !strings.Contains(out.String(), "已取消") {
593			t.Fatalf("取消输出应包含原工单编号与已取消状态: %s", out.String())
594		}
595		s, err := openStore(dir)
596		if err != nil {
597			t.Fatal(err)
598		}
599		if got := s.findTicket("T0001"); got.Status != ticketCancelled {
600			t.Fatalf("取消后状态 = %q", got.Status)
601		}
602		// 取消后新报修仍因编号耗尽被拒绝。
603		if _, _, err := s.report("EQ-1", "新故障", "req-2"); err == nil {
604			t.Fatal("编号耗尽时新报修应继续被拒绝")
605		}
606	}
607	
608	// 履历序号耗尽时取消失败，不留下部分变化，原文件字节不变。
609	func TestEventSeqExhaustionRejectsCancel(t *testing.T) {
610		dir := t.TempDir()
611		raw := writeLedger(t, dir, func(m map[string]any) {
612			m["events"].([]any)[0].(map[string]any)["seq"] = math.MaxInt
613		})
614		s, err := openStore(dir)
615		if err != nil {
616			t.Fatalf("合法台账应能加载: %v", err)
617		}
618		if _, _, err := s.cancelTicket("T0001", "误报"); err == nil ||
619			!strings.Contains(err.Error(), "履历序号") {
620			t.Fatalf("履历序号耗尽应拒绝取消，得到 %v", err)
621		}
622		if got := s.findTicket("T0001"); got.Status != ticketOpen {
623			t.Fatal("失败的取消不应改动工单状态")
624		}
625		if got := s.findAsset("EQ-1").Status; got != statusRepairing {
626			t.Fatal("失败的取消不应改动资产状态")
627		}
628		got, err := os.ReadFile(filepath.Join(dir, dataFileName))
629		if err != nil || !bytes.Equal(got, raw) {
630			t.Fatal("失败的取消不应改动原文件")
631		}
632	}
633	
634	// 报修计数器检查应先于任何数据修改：失败路径不绑定请求标识。
635	func TestFailedReportBindsNothing(t *testing.T) {
636		s := newTestStore(t)
637		if _, err := s.registerAsset("EQ-1", "打印机", "一楼"); err != nil {
638			t.Fatal(err)
639		}
640		if _, _, err := s.report("NOPE", "卡纸", "req-x"); err == nil {
641			t.Fatal("未知资产报修应失败")
642		}
643		if s.findRequest("req-x") != nil {
644			t.Fatal("失败的报修不应绑定请求标识")
645		}
646		if _, _, err := s.report("EQ-1", "卡纸", "req-x"); err != nil {
647			t.Fatalf("同一标识应可用于后续成功报修: %v", err)
648		}
649		if err := s.save(); err != nil {
650			t.Fatal(err)
651		}
652		s2, err := openStore(s.dir)
653		if err != nil {
654			t.Fatal(err)
655		}
656		if got := len(s2.data.Requests); got != 1 {
657			t.Fatalf("重载后应只有一条绑定，得到 %d", got)
658		}
659	}
