246	// 派工链矛盾的数据在加载时报错并保留原文件。
247	func TestAssignChainContradiction(t *testing.T) {
248		assignEvent := func(seq int, from, to string) map[string]any {
249			return map[string]any{
250				"seq": seq, "asset_id": "EQ-1", "ticket_id": "T0001",
251				"kind": "派工", "content": "说明", "from": from, "to": to,
252				"time": "2026-10-01T10:00:00Z",
253			}
254		}
255		cases := []struct {
256			name   string
257			mutate func(m map[string]any)
258		}{
259			{"首次派工原负责人不为空", func(m map[string]any) {
260				appendTo(m, "events", assignEvent(4, "张三", "李四"))
261				tk := m["tickets"].([]any)[0].(map[string]any)
262				tk["assignee"] = "李四"
263				tk["assigned_at"] = "2026-10-01T10:00:00Z"
264				tk["assign_note"] = "说明"
265			}},
266			{"转派原负责人不接续", func(m map[string]any) {
267				appendTo(m, "events", assignEvent(4, "", "张三"))
268				appendTo(m, "events", assignEvent(5, "王五", "李四"))
269				tk := m["tickets"].([]any)[0].(map[string]any)
270				tk["assignee"] = "李四"
271				tk["assigned_at"] = "2026-10-01T10:00:00Z"
272				tk["assign_note"] = "说明"
273			}},
274			{"派工新负责人为空", func(m map[string]any) {
275				appendTo(m, "events", assignEvent(4, "", ""))
276			}},
277			{"派工新旧负责人相同", func(m map[string]any) {
278				appendTo(m, "events", assignEvent(4, "张三", "张三"))
279			}},
280			{"工单负责人与履历不符", func(m map[string]any) {
281				appendTo(m, "events", assignEvent(4, "", "张三"))
282				tk := m["tickets"].([]any)[0].(map[string]any)
283				tk["assignee"] = "李四"
284				tk["assigned_at"] = "2026-10-01T10:00:00Z"
285				tk["assign_note"] = "说明"
286			}},
287			{"有派工履历但工单未派工", func(m map[string]any) {
288				appendTo(m, "events", assignEvent(4, "", "张三"))
289			}},
290			{"工单已派工但无派工履历", func(m map[string]any) {
291				tk := m["tickets"].([]any)[0].(map[string]any)
292				tk["assignee"] = "张三"
293				tk["assigned_at"] = "2026-10-01T10:00:00Z"
294				tk["assign_note"] = "说明"
295			}},
296			{"未派工工单带派工时间", func(m map[string]any) {
297				m["tickets"].([]any)[0].(map[string]any)["assigned_at"] = "2026-10-01T10:00:00Z"
298			}},
299			{"已派工工单缺派工说明", func(m map[string]any) {
300				appendTo(m, "events", assignEvent(4, "", "张三"))
301				tk := m["tickets"].([]any)[0].(map[string]any)
302				tk["assignee"] = "张三"
303				tk["assigned_at"] = "2026-10-01T10:00:00Z"
304			}},
305			{"保存说明与最后派工履历不符", func(m map[string]any) {
306				appendTo(m, "events", assignEvent(4, "", "张三"))
307				tk := m["tickets"].([]any)[0].(map[string]any)
308				tk["assignee"] = "张三"
309				tk["assigned_at"] = "2026-10-01T10:00:00Z"
310				tk["assign_note"] = "另一份说明"
311			}},
312			{"终结后出现派工履历", func(m map[string]any) {
313				cancelLedger(m)
314				appendTo(m, "events", assignEvent(5, "", "张三"))
315				tk := m["tickets"].([]any)[0].(map[string]any)
316				tk["assignee"] = "张三"
317				tk["assigned_at"] = "2026-10-01T10:30:00Z"
318				tk["assign_note"] = "说明"
319			}},
320			{"报修之前出现派工履历", func(m map[string]any) {
321				ev := assignEvent(2, "", "张三")
322				ev["time"] = "2026-10-01T07:00:00Z"
323				appendTo(m, "events", ev)
324				tk := m["tickets"].([]any)[0].(map[string]any)
325				tk["assignee"] = "张三"
326				tk["assigned_at"] = "2026-10-01T07:00:00Z"
327				tk["assign_note"] = "说明"
328			}},
329			{"非派工履历带派工字段", func(m map[string]any) {
330				m["events"].([]any)[0].(map[string]any)["to"] = "张三"
331			}},
332		}
333		for _, c := range cases {
334			t.Run(c.name, func(t *testing.T) {
335				dir := t.TempDir()
336				raw := writeLedger(t, dir, c.mutate)
337				if _, err := openStore(dir); err == nil {
338					t.Fatal("矛盾数据应报错")
339				} else if !strings.Contains(err.Error(), "原文件已保留") {
340					t.Fatalf("错误应说明保留原文件: %v", err)
341				}
342				got, err := os.ReadFile(filepath.Join(dir, dataFileName))
343				if err != nil {
344					t.Fatal(err)
345				}
346				if string(got) != string(raw) {
347					t.Fatal("加载失败后原文件字节应不变")
348				}
349			})
350		}
351	}
