353	// 派工变化一次原子保存；失败不留部分变化，恢复后可重试，重载后状态保持。
354	func TestAssignFailureThenReload(t *testing.T) {
355		s := newTestStore(t)
356		if _, err := s.registerAsset("EQ-1", "打印机", "一楼"); err != nil {
357			t.Fatal(err)
358		}
359		if _, _, err := s.report("EQ-1", "卡纸", "req-1"); err != nil {
360			t.Fatal(err)
361		}
362		if _, err := s.assignTicket("T0001", "张三", "首次派工"); err != nil {
363			t.Fatal(err)
364		}
365		if err := s.save(); err != nil {
366			t.Fatal(err)
367		}
368		path := filepath.Join(s.dir, dataFileName)
369		rawBefore, err := os.ReadFile(path)
370		if err != nil {
371			t.Fatal(err)
372		}
373	
374		// 失败派工（重复派给当前人员）不产生任何变化，保存后文件字节不变。
375		if _, err := s.assignTicket("T0001", "张三", "重复"); !errors.Is(err, errConflict) {
376			t.Fatalf("重复派工应冲突，得到 %v", err)
377		}
378		if err := s.save(); err != nil {
379			t.Fatal(err)
380		}
381		rawAfter, err := os.ReadFile(path)
382		if err != nil {
383			t.Fatal(err)
384		}
385		if string(rawBefore) != string(rawAfter) {
386			t.Fatal("失败派工后保存不应改变文件内容")
387		}
388	
389		// 目录不可写时保存失败：内存中的转派不落入文件，恢复后可重试。
390		if _, err := s.assignTicket("T0001", "李四", "转派"); err != nil {
391			t.Fatal(err)
392		}
393		if err := os.Chmod(s.dir, 0o555); err != nil {
394			t.Fatal(err)
395		}
396		saveErr := s.save()
397		if err := os.Chmod(s.dir, 0o755); err != nil {
398			t.Fatal(err)
399		}
400		if saveErr == nil {
401			t.Skip("当前环境允许只读目录写入，跳过保存失败分支")
402		}
403		rawNow, err := os.ReadFile(path)
404		if err != nil {
405			t.Fatal(err)
406		}
407		if string(rawNow) != string(rawAfter) {
408			t.Fatal("保存失败不应留下部分变化")
409		}
410		// 恢复写入条件后重试成功。
411		if err := s.save(); err != nil {
412			t.Fatalf("恢复后重试保存应成功: %v", err)
413		}
414	
415		// 重载：负责人、履历与请求去重结果保持。
416		s2, err := openStore(s.dir)
417		if err != nil {
418			t.Fatal(err)
419		}
420		tk := s2.findTicket("T0001")
421		if tk.Assignee != "李四" || tk.AssignNote != "转派" {
422			t.Fatalf("重载后负责人信息不正确: %+v", tk)
423		}
424		events := s2.eventsOf("EQ-1")
425		if len(events) != 3 || events[2].Kind != eventAssign || events[2].From != "张三" || events[2].To != "李四" {
426			t.Fatalf("重载后履历不正确: %+v", events)
427		}
428		old, replay, err := s2.report("EQ-1", "卡纸", "req-1")
429		if err != nil || !replay || old.ID != "T0001" || old.Assignee != "李四" {
430			t.Fatalf("重载后请求去重应保持: %v replay=%v err=%v", old, replay, err)
431		}
432	}
