		tt := getTimes(e.TicketID)
		switch e.Kind {
		case eventReport:
			tt.reportAt = e.Time
			tt.hasReport = true
		case eventClose:
			tt.closedAt = e.Time
			tt.hasCloseCancel = true
		case eventCancel:
			tt.cancelledAt = e.Time
			tt.hasCloseCancel = true
		}
