// 有效旧台账无需转换：间隔、乱序、取消单、重复时间字段不一致都按履历序号配对。
func TestDowntimeLegacyShuffledLedger(t *testing.T) {
	dir := t.TempDir()
	writeRawLedger(t, dir, shuffledLegacyLedger)
	s, err := openStore(dir)
	if err != nil {
		t.Fatalf("有效旧台账应能加载: %v", err)
