25	func mustTime(t *testing.T, s string) time.Time {
26		t.Helper()
27		tm, err := time.Parse(time.RFC3339Nano, s)
28		if err != nil {
29			t.Fatalf("解析时刻 %q: %v", s, err)
30		}
31		return tm
32	}
